package com.cpf.batch.worker; import com.cpf.core.api.database.CpfDatabaseVendor; import org.springframework.batch.core.configuration.support.DefaultBatchConfiguration; import org.springframework.beans.factory.annotation.Qualifier; import org.springframework.core.env.Environment; import org.springframework.context.annotation.Configuration; import org.springframework.transaction.PlatformTransactionManager; import javax.sql.DataSource;
@Configuration
public class BatchRepositoryConfiguration extends DefaultBatchConfiguration { private final DataSource ds;private final PlatformTransactionManager tx;private final String db;public BatchRepositoryConfiguration(@Qualifier("batDataSource")DataSource d,@Qualifier("batTransactionManager")PlatformTransactionManager t,Environment e){ds=d;tx=t;db=CpfDatabaseVendor.from(e.getProperty("cpf.db.vendor","mariadb")).springBatchDatabaseType();} protected DataSource getDataSource(){return ds;} protected PlatformTransactionManager getTransactionManager(){return tx;} protected String getDatabaseType(){return db;} }
